={
  "name": "Premier Health Location Assistant - {{ $('Setup Configuration Form').item.json['Organization Name'] }}",
  "voice": {
    "model": "eleven_flash_v2_5",
    "voiceId": "bIHbv24MWmeRgasZH58o",
    "autoMode": true,
    "provider": "11labs",
    "stability": 0.5,
    "similarityBoost": 0.75,
    "useSpeakerBoost": true,
    "optimizeStreamingLatency": 3,
    "inputPunctuationBoundaries": [".", "!", "?", ";", ","]
  },
  "model": {
    "model": "gpt-4o-mini",
    "toolIds": [],
    "messages": [
      {
        "role": "system",
        "content": "You are a helpful healthcare location assistant for {{ $('Setup Configuration Form').item.json['Organization Name'] }} serving the {{ $('Setup Configuration Form').item.json['Service Area'] }} area. You help customers find healthcare providers including doctors, hospitals, clinics, and pharmacies.\n\nYour capabilities include:\n- Searching for healthcare providers by location, specialty, or provider type\n- Finding emergency healthcare providers\n- Getting detailed provider information\n- Sending provider information via email or SMS\n- Escalating complex queries to customer support\n\nThe current date and time is: {{ new Date().toISOString() }}.\n\nWhen helping customers:\n1. Always ask clarifying questions about their location preferences\n2. Confirm the type of healthcare service they need\n3. Offer to send information via email or SMS\n4. For urgent/emergency situations, prioritize emergency provider search\n5. If you cannot find what they're looking for, offer to escalate to customer support\n\nKey service areas: {{ $('Setup Configuration Form').item.json['Service Area'] }} and surrounding regions.\n\nAlways be empathetic and understanding, as customers may be dealing with health concerns."
      }
    ],
    "provider": "openai",
    "maxTokens": 200
  },
  "firstMessage": "Hello! I'm your Premier Health location assistant. I can help you find doctors, hospitals, clinics, and pharmacies in the {{ $('Setup Configuration Form').item.json['Service Area'] }} area. How may I assist you today?",
  "voicemailMessage": "Thank you for calling Premier Health. Please call back during our service hours or visit our website for assistance.",
  "endCallFunctionEnabled": true,
  "endCallMessage": "Thank you for calling Premier Health. Have a great day and stay healthy!",
  "transcriber": {
    "model": "nova-3-general",
    "language": "en",
    "numerals": true,
    "provider": "deepgram"
  },
  "serverMessages": [
    "end-of-call-report",
    "function-call",
    "tool-calls"
  ],
  "dialKeypadFunctionEnabled": true,
  "analysisPlan": {
    "minMessagesThreshold": 2,
    "summaryPlan": {
      "messages": [
        {
          "content": "Create a detailed summary of this healthcare location assistance call. Include: customer intent, location searched, providers found, actions taken, and overall satisfaction. Extract any contact information (email, phone) provided by the caller.",
          "role": "system"
        },
        {
          "content": "Here is the transcript:\n\n\n\n. Here is the ended reason of the call:\n\n\n\n",
          "role": "user"
        }
      ],
      "timeoutSeconds": 25
    },
    "structuredDataPlan": {
      "enabled": true,
      "schema": {
        "type": "object",
        "required": ["score", "result", "customer_intent", "location_searched", "providers_found", "actions_taken"],
        "properties": {
          "score": {
            "description": "Rate the call effectiveness from 1-10",
            "type": "number"
          },
          "result": {
            "description": "Brief outcome of the call",
            "type": "string"
          },
          "customer_intent": {
            "description": "What healthcare service the customer was looking for",
            "type": "string"
          },
          "location_searched": {
            "description": "Geographic area or location customer was interested in",
            "type": "string"
          },
          "providers_found": {
            "description": "Number of relevant healthcare providers found",
            "type": "number"
          },
          "actions_taken": {
            "description": "Actions performed during the call (search, email, escalation, etc.)",
            "type": "string"
          },
          "customer_email": {
            "description": "Email address provided by customer",
            "type": "string"
          },
          "customer_phone": {
            "description": "Phone number of the caller",
            "type": "string"
          },
          "escalated_to_support": {
            "description": "Whether the call was escalated to human support",
            "type": "boolean"
          }
        }
      },
      "messages": [
        {
          "content": "Extract structured data from this healthcare assistance call. Follow the schema exactly and provide accurate information.",
          "role": "system"
        },
        {
          "content": "Here is the transcript:\n\n\n\n. Here is the ended reason of the call:\n\n\n\n",
          "role": "user"
        }
      ],
      "timeoutSeconds": 30
    },
    "successEvaluationPlan": {
      "rubric": "PassFail",
      "messages": [
        {
          "content": "Evaluate if this healthcare assistance call was successful. Consider: Did we help the customer find what they needed? Was the interaction helpful and professional? Return true for successful calls, false only if the customer was frustrated or we failed to provide assistance.",
          "role": "system"
        },
        {
          "content": "Here is the transcript:\n\n\n\n. Here is the ended reason:\n\n\n\n",
          "role": "user"
        }
      ],
      "timeoutSeconds": 15
    }
  },
  "voicemailDetection": {
    "provider": "vapi",
    "backoffPlan": {
      "maxRetries": 3,
      "startAtSeconds": 3,
      "frequencySeconds": 5
    }
  },
  "backgroundDenoisingEnabled": true,
  "artifactPlan": {
    "recordingFormat": "mp3"
  },
  "messagePlan": {
    "idleMessages": [
      "I'm here to help you find healthcare providers. What can I assist you with?",
      "Is there a specific type of healthcare service you're looking for?",
      "Would you like me to search for providers in a particular area?",
      "I can help you find doctors, hospitals, clinics, or pharmacies. What do you need?"
    ]
  },
  "startSpeakingPlan": {
    "smartEndpointingPlan": {
      "provider": "vapi"
    }
  }
}

