parameters.jsCode:
// Update the assistant with the tool IDs
const items = $input.all();

// Extract tool IDs from all the created tools
const toolIds = [];

// Get tool IDs from each tool creation response
for (let i = 2; i < items.length; i++) {
  const item = items[i];
  if (item.json && item.json.id) {
    toolIds.push(item.json.id);
  }
}

// Get the assistant ID from the first response
const assistantId = items[1].json?.id;

console.log('Tool IDs collected:', toolIds);
console.log('Assistant ID:', assistantId);

return [{
  json: {
    assistant_id: assistantId,
    tool_ids: toolIds,
    server_url: items[0].json['Server URL'],
    organization_name: items[0].json['Organization Name'],
    service_area: items[0].json['Service Area'],
    support_email: items[0].json['Support Email']
  }
}];

// Prepare final configuration summary
const items = $input.all();
const config = items[0].json;
const assistantResponse = items[1].json;
const phoneResponse = items[2].json;

const summary = {
  success: true,
  setup_completed_at: new Date().toISOString(),
  configuration: {
    organization_name: config.organization_name,
    service_area: config.service_area,
    support_email: config.support_email,
    server_url: config.server_url
  },
  vapi_resources: {
    assistant_id: config.assistant_id,
    assistant_name: assistantResponse?.name || 'Premier Health Location Assistant',
    phone_number: phoneResponse?.number || 'Phone number pending activation',
    phone_number_id: phoneResponse?.id,
    tools_count: config.tool_ids?.length || 0,
    tool_ids: config.tool_ids
  },
  capabilities: [
    'Healthcare provider search by location and specialty',
    'Emergency provider lookup',
    'Provider information via email',
    'Provider information via SMS',
    'Freshdesk support escalation',
    'Call analytics and reporting'
  ],
  webhook_endpoint: `${config.server_url}/premier-health/vapi-webhook`,
  next_steps: [
    'Test the voice assistant by calling the provided phone number',
    'Configure Freshdesk credentials in the backend',
    'Set up monitoring and analytics dashboards',
    'Train staff on escalation procedures'
  ]
};

console.log('Premier Health Voice Assistant Setup Complete:', JSON.stringify(summary, null, 2));

return [{ json: summary }];
